from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])

    # The uniform separator is the one nearest the center of the grid.
    separators = [
        c for c in range(w)
        if all(grid[r][c] == grid[0][c] for r in range(h))
    ]
    sep = min(separators, key=lambda c: abs(c - (w - 1) / 2))

    left = [row[:sep] for row in grid]
    right = [row[sep + 1:] for row in grid]

    def mode(panel):
        return Counter(v for row in panel for v in row).most_common(1)[0][0]

    left_bg, right_bg = mode(left), mode(right)
    out = []

    if left_bg == right_bg:
        for r in range(h):
            out.append([
                2 if left[r][c] != left_bg or right[r][c] != right_bg else 3
                for c in range(len(left[r]))
            ])
    else:
        shared = set(v for row in left for v in row) & set(
            v for row in right for v in row
        )
        common = next(iter(shared))
        for r in range(h):
            out.append([
                3 if left[r][c] == common and right[r][c] == common else common
                for c in range(len(left[r]))
            ])

    return out
